D = G+dis1*dir(d1);
F = G+dis2*dir(d2);
E = D+dis2*dir(d2);
X = A+.5*dis1*dir(d1);
Y = C+.5*dis2*dir(d2);
Z = (0,4);

fill(G--D--E--F--cycle, gray(0.8));
fill(O--F--G--cycle, gray(0.8));
fill(O--D--G--cycle, gray(0.8));
draw(G--D--E--F--cycle);
draw(G--O);
draw(F--C--O--A--D);
